<?php

/**
 * Class IpSecurity
 *
 * Provides secure IP-based access control by correctly identifying
 * the client's real IP address, understanding the difference between
 * TCP-level IPs (REMOTE_ADDR) and spoofable HTTP headers.
 */
class IpSecurity
{
    /**
     * List of HTTP headers that clients can spoof.
     */
    const SPOOFABLE_HEADERS = [
        'HTTP_X_FORWARDED_FOR',
        'HTTP_CLIENT_IP',
        'HTTP_X_REAL_IP',
        'HTTP_X_FORWARDED',
        'HTTP_FORWARDED_FOR',
        'HTTP_FORWARDED',
    ];

    /**
     * Returns the direct TCP-level IP address from REMOTE_ADDR.
     *
     * This value comes from the actual TCP connection and cannot
     * be spoofed via HTTP headers.
     *
     * @param array $server The $_SERVER superglobal array
     * @return string|null The remote IP address or null if not set
     */
    public function getDirectIp(array $server)
    {
        return isset($server['REMOTE_ADDR']) ? $server['REMOTE_ADDR'] : null;
    }

    /**
     * Checks if a given header name is spoofable by the client.
     *
     * @param string $headerName The header name to check
     * @return bool True if the header can be spoofed, false otherwise
     */
    public function isSpoofableHeader(string $headerName): bool
    {
        return in_array(strtoupper($headerName), self::SPOOFABLE_HEADERS, true);
    }

    /**
     * Returns the real client IP address.
     *
     * If REMOTE_ADDR is in the trusted proxies list, the method
     * looks at HTTP_X_FORWARDED_FOR and returns the last untrusted
     * IP in the chain. Otherwise, it returns REMOTE_ADDR directly.
     *
     * @param array $server The $_SERVER superglobal array
     * @param array $trustedProxies List of trusted proxy IP addresses
     * @return string|null The resolved client IP address
     */
    public function getClientIp(array $server, array $trustedProxies = [])
    {
