<?php

/**
 * Class IpSecurity
 * 
 * Provides secure IP-based access control by correctly handling
 * the difference between TCP-level REMOTE_ADDR and spoofable HTTP headers.
 */
class IpSecurity
{
    /**
     * Headers that can be spoofed by the client.
     */
    const SPOOFABLE_HEADERS = [
        'HTTP_X_FORWARDED_FOR',
        'HTTP_CLIENT_IP',
        'HTTP_X_REAL_IP',
        'HTTP_X_FORWARDED',
        'HTTP_FORWARDED_FOR',
        'HTTP_FORWARDED',
    ];

    /**
     * Returns the value of REMOTE_ADDR from the provided server array.
     * This is the TCP-level IP and cannot be spoofed via HTTP headers.
     *
     * @param array $server The $_SERVER array or equivalent
     * @return string|null The direct IP address or null if not set
     */
    public function getDirectIp(array $server)
    {
        return isset($server['REMOTE_ADDR']) ? $server['REMOTE_ADDR'] : null;
    }

    /**
     * Returns true if the given header name is one that can be spoofed
     * by the client. Returns false for REMOTE_ADDR which comes from
     * the TCP connection.
     *
     * @param string $headerName The header name to check
     * @return bool True if spoofable, false otherwise
     */
    public function isSpoofableHeader(string $headerName): bool
    {
        return in_array(strtoupper($headerName), self::SPOOFABLE_HEADERS, true);
    }

    /**
     * Returns the real client IP address.
     * 
     * If REMOTE_ADDR is in the trusted proxies list, it looks at
     * HTTP_X_FORWARDED_FOR and returns the last untrusted IP in the chain.
     * Otherwise, it returns REMOTE_ADDR directly.
     *
     * @param array $server The $_SERVER array or equivalent
     * @param array $trustedProxies List of trusted proxy IP addresses
     * @return string|null The resolved client IP address
     */
    public function getClientIp(array $server, array $trustedProxies = [])
    {
        $remoteAddr = $this->getDirectIp($server);

        // If no REMOTE_ADDR, return null
        if ($remoteAddr === null) {
            return null;
        }

        // If REMOTE_ADDR is not a trusted proxy, return it directly
        if (!in_array($remoteAddr, $trustedProxies, true)) {
            return $remoteAddr;
        }

        // REMOTE_ADDR is a trusted proxy, so we need to look at X-Forwarded-For
        if (!isset($server['HTTP_X_FORWARDED_FOR']) || empty($server['HTTP_X_FORWARDED_FOR'])) {
            return $remoteAddr;
        }

        // Parse the X-Forwarded-For chain
        $forwardedIps = array_map('trim', explode(',', $server['HTTP_X_FORWARDED_FOR']));

        // Iterate from right to left to find the last untrusted IP
        for ($i = count($forwardedIps) - 1; $i >= 0; $i--) {
            $ip = trim($forwardedIps[$i]);
            if (!empty($ip) && !in_array($ip, $trustedProxies, true)) {
                return $ip;
            }
        }

        // All IPs in the chain are trusted, return REMOTE_ADDR
        return $remoteAddr;
    }

    /**
     * Returns true if the resolved client IP is in the admin IPs list.
     *
     * @param array $server The $_SERVER array or equivalent
     * @param array $adminIps List of admin IP addresses
     * @param array $trustedProxies List of trusted proxy IP addresses
     * @return bool True if the client IP is an admin IP, false otherwise
     */
    public function isAdminIp(array $server, array $adminIps, array $trustedProxies = []): bool
    {
        $clientIp = $this->getClientIp($server, $trustedProxies);
        return $clientIp !== null && in_array($clientIp, $adminIps, true);
    }
}
