import bisq.common.persistence.PersistenceManager;
import bisq.core.user.BlockChainExplorer;
import bisq.core.user.BlockchainExplorerSelection;
import bisq.core.user.Preferences;
import bisq.core.user.PreferencesPayload;

import java.io.File;
import java.lang.reflect.Field;
import java.util.ArrayList;

public class BsqExplorerRepro {

    static PersistenceManager<PreferencesPayload> newStubPM(File dir) {
        return new PersistenceManager<>(dir, null, null) {
            @Override
            public void forcePersistNow() {
                // no-op for repro
            }
        };
    }

    static Preferences newPreferences(File dir) {
        return new Preferences(newStubPM(dir), null, null, null,
                new ArrayList<>(), "", false, false, "", "", 0, false);
    }

    static boolean runScenario(String label, BlockChainExplorer initial, boolean expectUnchanged) throws Exception {
        File dir = new File("/tmp/bsq-repro/data-" + label);
        dir.mkdirs();
        Preferences preferences = newPreferences(dir);
        if (initial != null) {
            preferences.setBsqBlockChainExplorer(initial);
        }
        String before = preferences.getBsqBlockChainExplorer() == null
                ? "null" : preferences.getBsqBlockChainExplorer().getName();
        System.out.println("[" + label + "] before selection: " + before);

        Field f = Preferences.class.getDeclaredField("blockchainExplorerSelection");
        f.setAccessible(true);
        BlockchainExplorerSelection selection = (BlockchainExplorerSelection) f.get(preferences);
        selection.selectNodes();

        String after = preferences.getBsqBlockChainExplorer() == null
                ? "null" : preferences.getBsqBlockChainExplorer().getName();
        System.out.println("[" + label + "] after selection:  " + after);

        boolean unchanged = (initial == null && preferences.getBsqBlockChainExplorer() == null)
                || (initial != null && preferences.getBsqBlockChainExplorer() == initial);
        boolean ok;
        if (expectUnchanged && !unchanged) {
            System.out.println("[" + label + "] FAIL: configured explorer was overwritten");
            ok = false;
        } else if (!expectUnchanged && unchanged) {
            System.out.println("[" + label + "] FAIL: explorer should have been (re)selected but was not");
            ok = false;
        } else {
            System.out.println("[" + label + "] OK");
            ok = true;
        }
        return ok;
    }

    public static void main(String[] args) throws Exception {
        boolean allOk = true;

        // Scenario 1: valid, non-deprecated explorer configured -> must stay unchanged
        BlockChainExplorer validCustom = new BlockChainExplorer(
                "My Custom Explorer", "https://my-custom-explorer.example/tx/", "https://my-custom-explorer.example/address/");
        try {
            allOk &= runScenario("valid", validCustom, true);
        } catch (Throwable t) {
            System.out.println("[valid] FAIL: exception " + t);
            allOk = false;
        }

        // Scenario 2: deprecated explorer configured -> must be replaced with a valid one
        BlockChainExplorer deprecated = new BlockChainExplorer(
                "Deprecated Explorer", "https://bsq.bisq.services/tx/", "https://bsq.bisq.services/address/");
        try {
            allOk &= runScenario("deprecated", deprecated, false);
        } catch (Throwable t) {
            System.out.println("[deprecated] FAIL: exception " + t);
            allOk = false;
        }

        // Scenario 3: no explorer configured -> a valid one must be selected (no NPE)
        try {
            allOk &= runScenario("none", null, false);
        } catch (Throwable t) {
            System.out.println("[none] FAIL: exception " + t);
            allOk = false;
        }

        System.out.println(allOk ? "ALL SCENARIOS PASSED" : "SOME SCENARIOS FAILED");
        System.exit(allOk ? 0 : 1);
    }
}
